/**
 * project-stalled-detector cron.
 *
 * Runs daily at 03:15 UTC.
 * Calls the `mark_stalled_projects` Postgres function (SECURITY DEFINER,
 * PUBLIC revoked) which stamps `stalled_at = now()` on projects that have
 * been in planning/deposit_paid status for 45+ days without activity.
 *
 * Returns an int — the count of projects newly flagged as stalled.
 *
 * Requires the service-role client (RPC is revoked from PUBLIC).
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runProjectStalledDetector(): Promise<void> {
  const start = Date.now()
  const runLog = logger.child({ job: 'project-stalled-detector' })

  runLog.info('project-stalled-detector: calling mark_stalled_projects RPC')

  const { data, error } = await supabase.rpc('mark_stalled_projects')

  if (error) {
    runLog.error(
      { err: error, duration_ms: Date.now() - start },
      'project-stalled-detector: RPC failed',
    )
    // Exit non-zero so Railway marks the run as failed and fires an alert.
    process.exitCode = 1
    return
  }

  const count_flagged = typeof data === 'number' ? data : 0
  runLog.info(
    { job: 'project-stalled-detector', count_flagged, duration_ms: Date.now() - start },
    'project-stalled-detector: complete',
  )
}

/**
 * project-healing-auto-complete cron.
 *
 * Runs daily at 03:30 UTC.
 * Calls the `auto_complete_healing_projects` Postgres function (SECURITY DEFINER,
 * PUBLIC revoked) which transitions projects from `healing` → `complete` when
 * all healed photos are uploaded OR 8 weeks have elapsed since the final session.
 *
 * Returns an int — the count of projects auto-completed.
 *
 * Requires the service-role client (RPC is revoked from PUBLIC).
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runProjectHealingAutoComplete(): Promise<void> {
  const start = Date.now()
  const runLog = logger.child({ job: 'project-healing-auto-complete' })

  runLog.info('project-healing-auto-complete: calling auto_complete_healing_projects RPC')

  const { data, error } = await supabase.rpc('auto_complete_healing_projects')

  if (error) {
    runLog.error(
      { err: error, duration_ms: Date.now() - start },
      'project-healing-auto-complete: RPC failed',
    )
    // Exit non-zero so Railway marks the run as failed and fires an alert.
    process.exitCode = 1
    return
  }

  const count_completed = typeof data === 'number' ? data : 0
  runLog.info(
    { job: 'project-healing-auto-complete', count_completed, duration_ms: Date.now() - start },
    'project-healing-auto-complete: complete',
  )
}

