/**
 * Mark stalled projects — daily 03:15 UTC.
 * Calls mark_stalled_projects() (SECURITY DEFINER, service-role required).
 * Returns int: count of projects newly flagged as stalled.
 */
cron.schedule('15 3 * * *', () => {
  logger.info('cron: running project-stalled-detector')
  runProjectStalledDetector().catch((err: unknown) => {
    logger.error({ err }, 'cron: project-stalled-detector threw unexpectedly')
  })
})

/**
 * Auto-complete healing projects — daily 03:30 UTC.
 * Calls auto_complete_healing_projects() (SECURITY DEFINER, service-role required).
 * Returns int: count of projects transitioned healing → complete.
 */
cron.schedule('30 3 * * *', () => {
  logger.info('cron: running project-healing-auto-complete')
  runProjectHealingAutoComplete().catch((err: unknown) => {
    logger.error({ err }, 'cron: project-healing-auto-complete threw unexpectedly')
  })
})

logger.info('inkos-worker-cron: all cron jobs scheduled')
